css:
/* ─────────────────────────────────────────────────────────────
   GLASS  ·  VARIANCE 7 / MOTION 6 / DENSITY 4
   Web frosted-glass approximation (backdrop-filter + layered
   borders + highlight). Not Apple Liquid Glass, which is an
   Apple-platform material with no public web package.
   Radius rule: surfaces 20 · pills 999 · rating boxes 14.
   One accent per page = the subject you are inside.
   ───────────────────────────────────────────────────────────── */
:root{
  color-scheme:light dark;
  --paper:#eef0f3; --paper-deep:#e4e7ec;
  --ink:#151a20; --ink-soft:#4d565f; --ink-faint:#5e6873;
  --rule:rgba(21,26,32,.13); --rule-soft:rgba(21,26,32,.07);
  --track:rgba(21,26,32,.10);
  --accent:#3f4f4a;

  --glass:rgba(255,255,255,.58);
  --glass-strong:rgba(255,255,255,.76);
  --edge:rgba(255,255,255,.85);
  --edge-low:rgba(255,255,255,.45);
  --shade:rgba(24,32,45,.10);
  --shade-deep:rgba(24,32,45,.16);

  --red:#bc4430; --amber:#d39b2c; --green:#1e5c52;
  --on-red:#fff; --on-amber:#1b2a27; --on-green:#fff;
  --red-ink:#9c3322; --amber-ink:#7d5410; --green-ink:#17504a;

  --focus:var(--accent);
  --gutter:104px;
  --r-surface:20px; --r-pill:999px; --r-box:14px;
  --sans:"Outfit","Segoe UI",system-ui,sans-serif;
  --mono:"JetBrains Mono",ui-monospace,"SF Mono",Menlo,monospace;

  --ease-out:cubic-bezier(.23,1,.32,1);
  --ease-spring:cubic-bezier(.34,1.42,.48,1);
  --ease-in-out:cubic-bezier(.77,0,.175,1);
}
@media (prefers-color-scheme:dark){
  :root{
    --paper:#0f1216; --paper-deep:#0a0c0f;
    --ink:#e9edf1; --ink-soft:#a3aeb9; --ink-faint:#8d98a3;
    --rule:rgba(255,255,255,.14); --rule-soft:rgba(255,255,255,.07);
    --track:rgba(255,255,255,.09);
    --accent:#8fa39c;

    --glass:rgba(255,255,255,.055);
    --glass-strong:rgba(255,255,255,.085);
    --edge:rgba(255,255,255,.20);
    --edge-low:rgba(255,255,255,.09);
    --shade:rgba(0,0,0,.34);
    --shade-deep:rgba(0,0,0,.48);

    --red:#e0765c; --amber:#edc266; --green:#54b39a;
    --on-red:#120906; --on-amber:#150f04; --on-green:#03130f;
    --red-ink:#eb9077; --amber-ink:#edc266; --green-ink:#6cc4ab;
  }
}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth;-webkit-tap-highlight-color:transparent;overscroll-behavior-y:none}
body{
  margin:0;min-height:100dvh;background:var(--paper);color:var(--ink);
  font-family:var(--sans);font-size:15px;line-height:1.55;font-weight:400;
  -webkit-font-smoothing:antialiased;
  transition:background-color 380ms var(--ease-in-out),color 380ms var(--ease-in-out);
}
/* the field the glass sits on: two soft accent washes, fixed so nothing repaints on scroll */
body::before{
  content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;
  background:
    radial-gradient(62% 48% at 10% 0%, color-mix(in srgb,var(--accent) 38%,transparent), transparent 72%),
    radial-gradient(58% 46% at 94% 20%, color-mix(in srgb,var(--accent) 24%,transparent), transparent 70%),
    linear-gradient(180deg,transparent 40%,var(--paper-deep));
  transition:background 420ms var(--ease-in-out);
}
.wrap{max-width:1080px;margin:0 auto;
  padding:0 max(22px,env(safe-area-inset-right)) calc(110px + env(safe-area-inset-bottom)) max(22px,env(safe-area-inset-left))}
button,[role="button"]{touch-action:manipulation;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none}
button{font:inherit;color:inherit;cursor:pointer}

/* ── the glass surface, used by every panel ── */
.pane{
  position:relative;isolation:isolate;border-radius:var(--r-surface);
  background:var(--glass);border:1px solid var(--edge-low);
  backdrop-filter:blur(26px) saturate(175%);-webkit-backdrop-filter:blur(26px) saturate(175%);
  box-shadow:inset 0 1px 0 var(--edge), 0 1px 2px var(--shade), 0 16px 40px -22px var(--shade-deep);
}
@media (prefers-reduced-transparency:reduce){
  .pane{background:var(--glass-strong);backdrop-filter:none;-webkit-backdrop-filter:none}
}

/* ── masthead: asymmetric split, not centred ── */
.masthead{padding:76px 0 14px;display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:44px;align-items:end}
#subject-view .masthead{padding:14px 0 10px;display:block}
h1{font-size:clamp(38px,5.6vw,66px);font-weight:600;line-height:1.02;letter-spacing:-.035em;margin:0}
#subject-title{font-size:clamp(32px,4.6vw,50px)}
.standfirst{grid-column:1;margin:18px 0 0;max-width:42ch;color:var(--ink-soft);font-size:16px}

.backlink{background:none;border:0;padding:9px 16px 9px 13px;font:inherit;font-size:13.5px;font-weight:500;color:var(--ink-soft);
  display:inline-flex;gap:8px;align-items:center;margin-top:34px;border-radius:var(--r-pill);
  background:var(--glass);border:1px solid var(--edge-low);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);
  box-shadow:inset 0 1px 0 var(--edge);
  transition:color 180ms var(--ease-out),transform 180ms var(--ease-spring),box-shadow 180ms var(--ease-out)}
.backlink:active{transform:scale(.96)}
.backlink:focus-visible{outline:2px solid var(--focus);outline-offset:3px}

/* ── bars ── */
.bar{display:flex;height:10px;border-radius:var(--r-pill);overflow:hidden;background:var(--track)}
.totals .bar{height:14px}
.mini .bar{height:9px}
.seg{height:100%}
.seg[data-s="3"]{background:var(--green)}
.seg[data-s="2"]{background:var(--amber)}
.seg[data-s="1"]{background:var(--red)}
@media (prefers-reduced-motion:no-preference){.seg{transition:width 420ms var(--ease-out)}}

/* ── totals panel: the right half of the split hero ── */
.totals{grid-column:2;grid-row:1 / span 2;align-self:stretch;padding:24px 24px 20px;margin:0;
  border-radius:var(--r-surface);background:var(--glass);border:1px solid var(--edge-low);
  backdrop-filter:blur(26px) saturate(175%);-webkit-backdrop-filter:blur(26px) saturate(175%);
  box-shadow:inset 0 1px 0 var(--edge), 0 1px 2px var(--shade), 0 16px 40px -22px var(--shade-deep)}
@media (prefers-reduced-transparency:reduce){.totals{background:var(--glass-strong);backdrop-filter:none}}
.totals-row{display:grid;grid-template-columns:22px 1fr 96px;gap:13px;align-items:center;margin-bottom:11px}
.totals-row:last-child{margin-bottom:0}
.tag{font-family:var(--mono);font-size:11px;font-weight:500;color:var(--ink-faint);font-variant-numeric:tabular-nums}
.count{font-family:var(--mono);font-size:11.5px;color:var(--ink-soft);text-align:right;font-variant-numeric:tabular-nums}
.count b{font-weight:600;color:var(--ink)}

/* ── legend: the colour key, doubles as the instructions ── */
.legend-key{display:flex;flex-wrap:wrap;gap:7px;margin-top:18px;padding-top:16px;border-top:1px solid var(--rule-soft)}
.key{display:inline-flex;align-items:center;gap:8px;font-size:12px;color:var(--ink-soft);
  padding:5px 11px 5px 7px;border-radius:var(--r-pill);background:var(--glass);border:1px solid var(--edge-low)}
.key i{width:11px;height:11px;border-radius:4px;flex:0 0 auto}
.key[data-s="1"] i{background:var(--red)}
.key[data-s="2"] i{background:var(--amber)}
.key[data-s="3"] i{background:var(--green)}

.section-label{font-size:11.5px;letter-spacing:.09em;text-transform:uppercase;color:var(--ink-faint);font-weight:500;margin:52px 0 14px}

/* ── subject bento: 5 items, 5 cells, first one is the feature ── */
#subject-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
#subject-list .subject:first-child{grid-column:1 / -1}
.subject{width:100%;text-align:left;border:1px solid var(--edge-low);padding:22px 22px 20px;font:inherit;color:inherit;
  border-radius:var(--r-surface);background:var(--glass);
  backdrop-filter:blur(26px) saturate(175%);-webkit-backdrop-filter:blur(26px) saturate(175%);
  box-shadow:inset 0 1px 0 var(--edge), 0 1px 2px var(--shade), 0 16px 40px -22px var(--shade-deep);
  display:grid;gap:18px;align-content:start;
  transition:transform 320ms var(--ease-spring),box-shadow 320ms var(--ease-out),border-color 320ms var(--ease-out)}
#subject-list .subject:first-child{grid-template-columns:1fr minmax(0,320px);align-items:center;gap:30px}
@media (prefers-reduced-transparency:reduce){.subject{background:var(--glass-strong);backdrop-filter:none}}
.subject:active{transform:scale(.988)}
.subject:focus-visible{outline:2px solid var(--focus);outline-offset:3px}
.subject h2{font-size:22px;font-weight:600;margin:0 0 5px;letter-spacing:-.022em;display:flex;align-items:center;gap:10px}
#subject-list .subject:first-child h2{font-size:29px}
.subject .dot{display:inline-block;width:10px;height:10px;border-radius:4px;background:var(--swatch,var(--accent));flex:0 0 auto}
.subject .meta{font-family:var(--mono);font-size:11.5px;color:var(--ink-faint);font-variant-numeric:tabular-nums}
.minis{display:flex;flex-direction:column;gap:7px}
.mini{display:grid;grid-template-columns:11px 1fr;gap:10px;align-items:center}
.mini span{font-family:var(--mono);font-size:10px;color:var(--ink-faint);font-variant-numeric:tabular-nums}

/* ── map ── */
.map{padding:20px 22px 16px;margin-top:20px;border-radius:var(--r-surface);
  background:var(--glass);border:1px solid var(--edge-low);
  backdrop-filter:blur(26px) saturate(175%);-webkit-backdrop-filter:blur(26px) saturate(175%);
  box-shadow:inset 0 1px 0 var(--edge), 0 1px 2px var(--shade), 0 16px 40px -22px var(--shade-deep)}
@media (prefers-reduced-transparency:reduce){.map{background:var(--glass-strong);backdrop-filter:none}}
.map-row{display:grid;grid-template-columns:22px 1fr 112px;gap:13px;align-items:center;margin-bottom:6px}
.map-groups{display:flex;gap:10px}
.map-group{display:flex;gap:2px}
.cell{position:relative;flex:1 1 0;height:18px;min-width:3px;padding:0;border:0;border-radius:4px;background:var(--track);
  animation:bloom 460ms var(--ease-spring) backwards}
.cell::after{content:"";position:absolute;inset:-5px -1px}
@keyframes bloom{from{opacity:0;transform:scale(.55) translateY(3px)}}
@keyframes beat{50%{transform:scaleY(1.5)}}
.cell:focus-visible{outline:2px solid var(--ink);outline-offset:2px;z-index:1}
.cell[data-state="1"]{background:var(--red)}
.cell[data-state="2"]{background:var(--amber)}
.cell[data-state="3"]{background:var(--green)}
.cell.beat{animation:beat 400ms var(--ease-out)}
.map-legend{display:grid;grid-template-columns:22px 1fr 112px;gap:13px;margin-top:10px}
.legend-groups{display:flex;gap:10px}
.legend-groups span{font-size:10px;letter-spacing:.02em;color:var(--ink-faint);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;border-top:1px solid var(--rule-soft);padding-top:6px}
.readout{margin:14px 0 0;min-height:1.5em;font-size:13px;color:var(--ink-soft)}
.readout b{font-weight:600;color:var(--ink)}

/* ── pass breakdown ── */
.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:14px}
.stat{padding:14px 15px 13px;border-radius:16px;background:var(--glass);border:1px solid var(--edge-low);
  box-shadow:inset 0 1px 0 var(--edge)}
.stat-n{display:block;font-family:var(--mono);font-size:26px;font-weight:600;letter-spacing:-.035em;line-height:1;font-variant-numeric:tabular-nums}
.stat[data-s="3"] .stat-n{color:var(--green-ink)}
.stat[data-s="2"] .stat-n{color:var(--amber-ink)}
.stat[data-s="1"] .stat-n{color:var(--red-ink)}
.stat[data-s="0"] .stat-n{color:var(--ink-faint)}
.stat-k{display:block;margin-top:7px;font-size:11.5px;line-height:1.35;color:var(--ink-soft)}

/* ── controls ── */
.controls{position:sticky;top:12px;z-index:5;margin-top:18px;padding:11px 14px max(11px,env(safe-area-inset-top));
  display:flex;flex-wrap:wrap;gap:10px 24px;align-items:center;border-radius:var(--r-pill);
  background:var(--glass-strong);border:1px solid var(--edge-low);
  backdrop-filter:blur(26px) saturate(175%);-webkit-backdrop-filter:blur(26px) saturate(175%);
  box-shadow:inset 0 1px 0 var(--edge), 0 10px 30px -18px var(--shade-deep)}
@media (prefers-reduced-transparency:reduce){.controls{background:var(--paper);backdrop-filter:none}}
.group{display:flex;align-items:center;gap:10px;flex-wrap:wrap;min-width:0}
.group-label{font-size:11.5px;color:var(--ink-faint);font-weight:500}
.chips{display:flex;gap:3px;flex-wrap:wrap}
.chip{white-space:nowrap;background:transparent;border:1px solid transparent;border-radius:var(--r-pill);padding:6px 14px;font-size:13px;font-weight:500;color:var(--ink-soft);
  transition:background-color 180ms var(--ease-out),color 180ms var(--ease-out),transform 180ms var(--ease-spring)}
.chip:active{transform:scale(.95)}
.chip[aria-pressed="true"]{background:var(--ink);color:var(--paper);box-shadow:0 2px 8px -2px var(--shade-deep)}
.chip:focus-visible{outline:2px solid var(--focus);outline-offset:2px}

/* ── points ── */
.area{margin-top:42px}
.area-head{display:flex;align-items:baseline;justify-content:space-between;gap:18px;padding:0 4px 12px}
.area-head h3{font-size:19px;font-weight:600;letter-spacing:-.022em;margin:0;display:flex;flex-wrap:wrap;align-items:baseline;gap:11px}
.area-pre{font-family:var(--mono);font-size:11px;font-weight:500;letter-spacing:.06em;text-transform:uppercase;color:var(--accent)}
.area-count{font-family:var(--mono);font-size:11.5px;color:var(--ink-soft);white-space:nowrap;font-variant-numeric:tabular-nums}
.point{display:grid;grid-template-columns:var(--gutter) 1fr;gap:20px;padding:18px 20px;scroll-margin-top:110px;
  border-radius:16px;border:1px solid transparent;
  transition:background-color 240ms var(--ease-out),border-color 240ms var(--ease-out)}
.point.flash{animation:wash 1500ms var(--ease-out)}
@keyframes wash{0%,55%{background:color-mix(in srgb,var(--accent) 20%,transparent);border-color:var(--edge-low)}}
.boxes{display:flex;gap:7px;padding-top:2px}
.box{width:30px;height:30px;border-radius:var(--r-box);border:1.5px solid var(--ink-faint);background:transparent;color:var(--ink-faint);
  font-family:var(--mono);font-size:12px;font-weight:500;line-height:1;display:flex;align-items:center;justify-content:center;padding:0;font-variant-numeric:tabular-nums;
  transition:background-color 200ms var(--ease-out),border-color 200ms var(--ease-out),color 200ms var(--ease-out),transform 200ms var(--ease-spring)}
.box:active{transform:scale(.88)}
.box:focus-visible{outline:2px solid var(--focus);outline-offset:2px}
.box[data-state="1"]{background:var(--red);border-color:var(--red);color:var(--on-red)}
.box[data-state="2"]{background:var(--amber);border-color:var(--amber);color:var(--on-amber)}
.box[data-state="3"]{background:var(--green);border-color:var(--green);color:var(--on-green)}
.point-id{font-family:var(--mono);font-size:11px;color:var(--ink-faint);font-variant-numeric:tabular-nums;margin-bottom:5px;letter-spacing:.04em}
.point-title{font-size:17px;font-weight:600;line-height:1.3;letter-spacing:-.018em;margin:0 0 6px}
.point-detail{margin:0;color:var(--ink-soft);font-size:13.5px;line-height:1.6;max-width:64ch}

.deck-head{display:flex;align-items:baseline;justify-content:space-between;gap:18px;margin-top:42px;padding:0 4px 12px;border-bottom:1px solid var(--rule)}
.deck-head h3{font-size:22px;font-weight:600;letter-spacing:-.025em;margin:0}
.deck-head span{font-family:var(--mono);font-size:11.5px;color:var(--ink-soft);font-variant-numeric:tabular-nums}
.deck-note{margin:14px 4px 20px;font-size:13px;color:var(--ink-soft);max-width:60ch}
.deck{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:14px}
.qcard{padding:17px 19px 15px;break-inside:avoid;border-radius:var(--r-surface);
  background:var(--glass);border:1px solid var(--edge-low);
  backdrop-filter:blur(26px) saturate(175%);-webkit-backdrop-filter:blur(26px) saturate(175%);
  box-shadow:inset 0 1px 0 var(--edge), 0 16px 40px -24px var(--shade-deep)}
@media (prefers-reduced-transparency:reduce){.qcard,.qz,.papers,.empty,.sync{background:var(--glass-strong);backdrop-filter:none}}
.qcard.red{box-shadow:inset 0 1px 0 var(--edge), inset 3px 0 0 var(--red), 0 16px 40px -24px var(--shade-deep)}
.qcard.amber{box-shadow:inset 0 1px 0 var(--edge), inset 3px 0 0 var(--amber), 0 16px 40px -24px var(--shade-deep)}
.qcard-head{display:flex;justify-content:space-between;align-items:baseline;gap:10px;margin-bottom:7px}
.qcard-head .n{font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.08em}
.qcard.red .n{color:var(--red-ink)}
.qcard.amber .n{color:var(--amber-ink)}
.qcard-head .refs{font-family:var(--mono);font-size:10px;color:var(--ink-faint);font-variant-numeric:tabular-nums}
.qcard h4{font-size:16.5px;font-weight:600;letter-spacing:-.018em;margin:0 0 6px;line-height:1.28}
.qcard .front{margin:0 0 9px;font-size:13px;color:var(--ink-soft)}
.qcard ul{margin:0;padding-left:16px}
.qcard li{font-size:13px;line-height:1.5;margin-bottom:5px}
.qz{padding:19px 21px 17px;margin-bottom:12px;border-radius:var(--r-surface);
  background:var(--glass);border:1px solid var(--edge-low);
  backdrop-filter:blur(26px) saturate(175%);-webkit-backdrop-filter:blur(26px) saturate(175%);
  box-shadow:inset 0 1px 0 var(--edge), 0 16px 40px -24px var(--shade-deep)}
.qz-head{display:flex;justify-content:space-between;align-items:baseline;gap:12px;margin-bottom:9px}
.qz-head .n{font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.08em;color:var(--accent)}
.qz-head .marks{font-family:var(--mono);font-size:10.5px;color:var(--ink-faint);font-variant-numeric:tabular-nums}
.qz .stem{margin:0 0 11px;font-size:14.5px;line-height:1.55}
.qz ol.opts{margin:0 0 11px;padding-left:21px}
.qz ol.opts li{font-size:13.5px;margin-bottom:4px}
.qz .reveal{background:transparent;border:1px solid var(--rule);border-radius:var(--r-pill);padding:6px 15px;font-size:12.5px;font-weight:500;color:var(--ink-soft);
  transition:border-color 180ms var(--ease-out),color 180ms var(--ease-out),transform 180ms var(--ease-spring)}
.qz .reveal:active{transform:scale(.95)}
.qz .reveal:focus-visible{outline:2px solid var(--focus);outline-offset:2px}
.qz .ans{margin-top:12px;padding-top:12px;border-top:1px solid var(--rule-soft)}
.qz .ans p{margin:0 0 7px;font-family:var(--mono);font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-faint)}
.qz .ans ul{margin:0;padding-left:16px}
.qz .ans li{font-size:13.5px;line-height:1.5;margin-bottom:5px}
.qz .src{margin:10px 0 0;font-size:12px;color:var(--ink-faint)}
.papers{margin-top:30px;padding:18px 20px;border-radius:var(--r-surface);background:var(--glass);border:1px solid var(--edge-low);
  backdrop-filter:blur(26px);box-shadow:inset 0 1px 0 var(--edge);font-size:13px;color:var(--ink-soft)}
.papers b{color:var(--ink);font-weight:600}
.print-row{margin-top:24px;display:flex;gap:9px;flex-wrap:wrap;align-items:center}
.print-row .hint{font-size:12.5px;color:var(--ink-faint)}
.empty{margin-top:46px;padding:48px 32px;border-radius:var(--r-surface);text-align:center;
  background:var(--glass);border:1px solid var(--edge-low);backdrop-filter:blur(26px);box-shadow:inset 0 1px 0 var(--edge)}
.empty strong{display:block;font-size:21px;font-weight:600;letter-spacing:-.022em;margin-bottom:7px}
.empty span{color:var(--ink-soft);font-size:14px}

/* ── sync + footer ── */
.sync{margin-top:56px;padding:22px 24px;border-radius:var(--r-surface);
  background:var(--glass);border:1px solid var(--edge-low);
  backdrop-filter:blur(26px) saturate(175%);-webkit-backdrop-filter:blur(26px) saturate(175%);
  box-shadow:inset 0 1px 0 var(--edge), 0 16px 40px -24px var(--shade-deep)}
.sync[data-live="true"]{box-shadow:inset 0 1px 0 var(--edge), inset 3px 0 0 var(--green), 0 16px 40px -24px var(--shade-deep)}
.sync[data-live="warn"]{box-shadow:inset 0 1px 0 var(--edge), inset 3px 0 0 var(--amber), 0 16px 40px -24px var(--shade-deep)}
.sync-head{font-size:11px;letter-spacing:.09em;text-transform:uppercase;color:var(--ink-faint);font-weight:500;margin:0 0 9px}
.sync-status{margin:0 0 15px;font-size:13.5px;max-width:60ch;color:var(--ink-soft)}
.sync-status b{color:var(--ink);font-weight:600}
.sync-actions{display:flex;flex-wrap:wrap;gap:8px}
footer{margin-top:38px;padding-top:24px;border-top:1px solid var(--rule-soft);display:flex;flex-wrap:wrap;gap:12px 10px;align-items:center;font-size:12.5px;color:var(--ink-soft)}
.ghost{background:var(--glass);border:1px solid var(--edge-low);border-radius:var(--r-pill);padding:8px 16px;font-size:12.5px;font-weight:500;
  backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);box-shadow:inset 0 1px 0 var(--edge);
  transition:border-color 180ms var(--ease-out),color 180ms var(--ease-out),transform 180ms var(--ease-spring)}
.ghost:active{transform:scale(.95)}
.ghost:focus-visible{outline:2px solid var(--focus);outline-offset:2px}
.ghost.danger{color:var(--red-ink)}
.status{margin-left:auto;text-align:right}
.status[data-warn="true"]{color:var(--red-ink)}
.colophon{flex-basis:100%;margin:0;max-width:62ch;color:var(--ink-faint);font-size:12px}
.hidden{display:none !important}
.sr-only{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}

@media (hover:hover) and (pointer:fine){
  .backlink:hover{color:var(--ink)}
  .subject:hover{transform:translateY(-3px);border-color:var(--edge);
    box-shadow:inset 0 1px 0 var(--edge), 0 2px 4px var(--shade), 0 26px 52px -24px var(--shade-deep)}
  .cell:hover{outline:2px solid var(--ink);outline-offset:2px;z-index:1}
  .chip:hover{background:var(--glass-strong);color:var(--ink)}
  .chip[aria-pressed="true"]:hover{background:var(--ink);color:var(--paper)}
  .point:hover{background:var(--glass);border-color:var(--edge-low)}
  .box:hover{border-color:var(--ink);color:var(--ink)}
  .box[data-state="1"]:hover{color:var(--on-red)}
  .box[data-state="2"]:hover{color:var(--on-amber)}
  .box[data-state="3"]:hover{color:var(--on-green)}
  .qz .reveal:hover{border-color:var(--ink);color:var(--ink)}
  .ghost:hover{border-color:var(--edge);color:var(--ink)}
  .ghost.danger:hover{border-color:var(--red-ink);color:var(--red-ink)}
}
@media (pointer:coarse){
  .box{width:44px;height:44px;border-radius:16px;font-size:14px}
  .boxes{gap:9px}
  :root{--gutter:152px}
  .chip{padding:10px 16px;font-size:14px}
  .ghost,.qz .reveal{padding:11px 18px}
  .cell{height:22px}
  .cell::after{inset:-8px -2px}
}
@media (prefers-contrast:more){
  :root{--glass:var(--paper);--glass-strong:var(--paper);--edge-low:var(--rule)}
  .box{border-width:2px}
  .chip{border-color:var(--rule)}
}
html.theming *,html.theming *::before,html.theming *::after{
  transition-property:background-color,border-color,color,box-shadow,outline-color;
  transition-duration:380ms;transition-timing-function:var(--ease-in-out)}

@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{animation-duration:.01ms !important;animation-iteration-count:1 !important;transition-duration:.01ms !important}
  .cell{animation:none}
  .subject:hover,.subject:active,.chip:active,.box:active,.ghost:active,.backlink:active,.qz .reveal:active{transform:none}
}

@media print{
  body{background:#fff;color:#000}
  body::before{display:none}
  .wrap{max-width:none;padding:0}
  .masthead{padding:0 0 10px;display:block}
  .backlink,.controls,.map,.stats,.sync,footer,#home,.deck-note,.print-row,.papers{display:none !important}
  .deck{grid-template-columns:repeat(2,1fr);gap:9px}
  .qcard{background:#fff;border:1px solid #bbb;box-shadow:none;backdrop-filter:none}
  .deck-head{page-break-after:avoid}
  .qz .ans{display:block}
  .reveal{display:none}
}

@media (max-width:900px){
  .masthead{grid-template-columns:1fr;gap:26px;padding:52px 0 10px}
  .totals{grid-column:1;grid-row:auto}
  #subject-list{grid-template-columns:1fr}
  #subject-list .subject:first-child{grid-template-columns:1fr;gap:18px}
  .stats{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media (max-width:620px){
  :root{--gutter:96px;--r-surface:18px}
  .wrap{padding-left:max(16px,env(safe-area-inset-left));padding-right:max(16px,env(safe-area-inset-right));padding-bottom:calc(84px + env(safe-area-inset-bottom))}
  .masthead{padding:36px 0 8px}
  .map-row,.map-legend,.totals-row{grid-template-columns:16px 1fr 62px;gap:8px}
  .map-groups{gap:4px}.map-group{gap:1px}
  .cell{height:16px;min-width:1px}
  .count{font-size:10.5px}
  .map-legend{display:none}
  .point{grid-template-columns:1fr;gap:12px;padding:16px 14px}
  .map,.totals,.subject{padding-left:16px;padding-right:16px}
  .status{margin-left:0;text-align:left;flex-basis:100%}
  .controls{top:8px;gap:8px 18px;padding:9px 12px max(9px,env(safe-area-inset-top))}
  .group{flex-wrap:nowrap;width:100%;gap:9px}
  .group-label{flex:0 0 auto}
  .chips{flex-wrap:nowrap;overflow-x:auto;overscroll-behavior-x:contain;scrollbar-width:none}
  .chips::-webkit-scrollbar{display:none}
}
@media (max-width:620px) and (pointer:coarse){
  .chip{padding:8px 14px}
  .cell{height:20px}
}

/* ─────────────────────────────────────────────────────────────
   POSTER  ·  VARIANCE 9 / MOTION 4 / DENSITY 6
   Swiss data-poster. Colour is structure, not decoration.
   Radius rule: everything is 0. No exceptions, no soft corners.
   One accent per page = the subject you are inside.
   ───────────────────────────────────────────────────────────── */
:root{
  color-scheme:light dark;
  --paper:#f2f1ed; --panel:#e7e5df; --ink:#14140f; --ink-soft:#4a4a42;
  --ink-faint:#5c5c53; --rule:#14140f; --rule-soft:rgba(20,20,15,.17);
  --track:rgba(20,20,15,.11);
  --accent:#3f4f4a; --on-accent:#f2f1ed;

  --red:#bc4430; --amber:#d39b2c; --green:#1e5c52;
  --on-red:#fff; --on-amber:#1b2a27; --on-green:#fff;
  --red-ink:#9c3322; --amber-ink:#7d5410; --green-ink:#17504a;

  --focus:var(--ink);
  --gutter:104px;
  --sans:"Archivo","Helvetica Neue",Helvetica,Arial,sans-serif;
  --mono:"JetBrains Mono",ui-monospace,"SF Mono",Menlo,monospace;
  --ease-out:cubic-bezier(.23,1,.32,1);
  --ease-in-out:cubic-bezier(.77,0,.175,1);
  --pad:max(22px,calc(50vw - 560px));
}
@media (prefers-color-scheme:dark){
  :root{
    --paper:#0c0c0a; --panel:#17170f; --ink:#f4f3ec; --ink-soft:#b0aea3;
    --ink-faint:#96948a; --rule:#f4f3ec; --rule-soft:rgba(244,243,236,.20);
    --track:rgba(244,243,236,.13);
    --accent:#9fb0a8; --on-accent:#0c0c0a;
    --red:#e0765c; --amber:#edc266; --green:#54b39a;
    --on-red:#160a07; --on-amber:#171004; --on-green:#03130f;
    --red-ink:#eb9077; --amber-ink:#edc266; --green-ink:#6cc4ab;
  }
}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth;-webkit-tap-highlight-color:transparent;overscroll-behavior-y:none;overflow-x:clip}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);font-size:14.5px;line-height:1.5;
  -webkit-font-smoothing:antialiased;font-variant-numeric:tabular-nums;
  transition:background-color 320ms var(--ease-in-out),color 320ms var(--ease-in-out)}
.wrap{max-width:1120px;margin:0 auto;
  padding:0 max(22px,env(safe-area-inset-right)) calc(96px + env(safe-area-inset-bottom)) max(22px,env(safe-area-inset-left))}
button,[role="button"]{touch-action:manipulation;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none}
button{font:inherit;color:inherit;cursor:pointer}
.bleed{width:100vw;margin-inline:calc(50% - 50vw);padding-inline:var(--pad)}

/* ── masthead ── */
.masthead{padding:56px 0 0}
h1{font-size:clamp(42px,8.2vw,100px);font-weight:800;font-stretch:112%;line-height:.88;letter-spacing:-.045em;
  text-transform:uppercase;margin:0;text-wrap:balance}
.standfirst{margin:22px 0 0;max-width:46ch;color:var(--ink-soft);font-size:15px}

/* the subject title sits inside a full-bleed accent band */
.subject-band{width:100vw;margin-inline:calc(50% - 50vw);background:var(--accent);color:var(--on-accent);
  padding:30px var(--pad) 26px;transition:background-color 320ms var(--ease-in-out)}
#subject-title{font-size:clamp(38px,8.4vw,96px);color:var(--on-accent)}
.backlink{background:none;border:0;padding:10px 0;font:inherit;font-family:var(--mono);font-size:11px;letter-spacing:.1em;
  text-transform:uppercase;color:var(--ink-soft);display:inline-flex;gap:8px;align-items:center;margin:26px 0 12px;
  transition:color 160ms var(--ease-out)}
.backlink:focus-visible{outline:2px solid var(--focus);outline-offset:3px}

/* ── bars ── */
.bar{display:flex;height:12px;overflow:hidden;background:var(--track)}
.totals .bar{height:22px}
.mini .bar{height:8px}
.seg{height:100%}
.seg[data-s="3"]{background:var(--green)}
.seg[data-s="2"]{background:var(--amber)}
.seg[data-s="1"]{background:var(--red)}
@media (prefers-reduced-motion:no-preference){.seg{transition:width 420ms var(--ease-out)}}

/* ── totals: full-bleed rule-bounded block ── */
.totals{border-top:3px solid var(--rule);border-bottom:1px solid var(--rule-soft);padding:22px 0 20px;margin-top:40px}
.totals-row{display:grid;grid-template-columns:34px 1fr 120px;gap:16px;align-items:center;margin-bottom:10px}
.totals-row:last-child{margin-bottom:0}
.tag{font-family:var(--mono);font-size:11px;font-weight:500;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-faint)}
.count{font-family:var(--mono);font-size:11.5px;color:var(--ink-soft);text-align:right}
.count b{font-weight:700;color:var(--ink)}

/* ── legend ── */
.legend-key{display:flex;flex-wrap:wrap;gap:0;margin-top:22px;border:1px solid var(--rule-soft)}
.key{display:inline-flex;align-items:center;gap:9px;font-family:var(--mono);font-size:10.5px;letter-spacing:.05em;
  text-transform:uppercase;color:var(--ink-soft);padding:10px 14px;flex:1 1 auto;border-right:1px solid var(--rule-soft)}
.key:last-child{border-right:0}
.key i{width:14px;height:14px;flex:0 0 auto}
.key[data-s="1"] i{background:var(--red)}
.key[data-s="2"] i{background:var(--amber)}
.key[data-s="3"] i{background:var(--green)}

.section-label{font-family:var(--mono);font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--ink-faint);margin:48px 0 0;
  padding-bottom:10px;border-bottom:1px solid var(--rule-soft)}

/* ── subject list: full-bleed rows, accent rule on the left ── */
#subject-list{border-top:0}
.subject{width:100%;text-align:left;background:transparent;border:0;border-bottom:1px solid var(--rule-soft);
  padding:26px 0 24px;font:inherit;color:inherit;display:grid;grid-template-columns:1fr minmax(0,300px);gap:34px;align-items:center;
  transition:background-color 200ms var(--ease-out),padding-left 260ms var(--ease-out)}
.subject:focus-visible{outline:2px solid var(--focus);outline-offset:-3px}
.subject h2{font-size:clamp(24px,3.4vw,38px);font-weight:800;font-stretch:108%;text-transform:uppercase;letter-spacing:-.032em;
  line-height:.98;margin:0 0 9px;display:flex;align-items:center;gap:14px}
.subject .dot{display:inline-block;width:16px;height:16px;background:var(--swatch,var(--accent));flex:0 0 auto}
.subject .meta{font-family:var(--mono);font-size:11px;letter-spacing:.05em;text-transform:uppercase;color:var(--ink-faint)}
.minis{display:flex;flex-direction:column;gap:7px}
.mini{display:grid;grid-template-columns:16px 1fr;gap:11px;align-items:center}
.mini span{font-family:var(--mono);font-size:10px;color:var(--ink-faint)}

/* ── map: the hero graphic, full bleed ── */
.map{width:100vw;margin-inline:calc(50% - 50vw);background:var(--panel);padding:30px var(--pad) 24px;
  transition:background-color 320ms var(--ease-in-out)}
.map-row{display:grid;grid-template-columns:34px 1fr 116px;gap:16px;align-items:center;margin-bottom:7px}
.map-groups{display:flex;gap:10px}
.map-group{display:flex;gap:2px}
.cell{position:relative;flex:1 1 0;height:30px;min-width:3px;padding:0;border:0;border-radius:0;background:var(--track);
  animation:rise 380ms var(--ease-out) backwards}
.cell::after{content:"";position:absolute;inset:-4px -1px}
@keyframes rise{from{opacity:0;transform:scaleY(.3)}}
@keyframes beat{50%{transform:scaleY(1.35)}}
.cell:focus-visible{outline:2px solid var(--ink);outline-offset:2px;z-index:1}
.cell[data-state="1"]{background:var(--red)}
.cell[data-state="2"]{background:var(--amber)}
.cell[data-state="3"]{background:var(--green)}
.cell.beat{animation:beat 380ms var(--ease-out)}
.map-legend{display:grid;grid-template-columns:34px 1fr 116px;gap:16px;margin-top:11px}
.legend-groups{display:flex;gap:10px}
.legend-groups span{font-family:var(--mono);font-size:9.5px;letter-spacing:.04em;text-transform:uppercase;color:var(--ink-faint);
  overflow:hidden;white-space:nowrap;text-overflow:ellipsis;border-top:1px solid var(--rule-soft);padding-top:7px}
.readout{margin:16px 0 0;min-height:1.5em;font-size:12.5px;color:var(--ink-soft)}
.readout b{font-weight:700;color:var(--ink)}

/* ── the breakdown: four giant numbers, colour as structure ── */
.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:0;margin-top:0;border-bottom:1px solid var(--rule-soft)}
.stat{padding:22px 18px 20px;border-right:1px solid var(--rule-soft);border-top:3px solid var(--track)}
.stat:last-child{border-right:0}
.stat[data-s="3"]{border-top-color:var(--green)}
.stat[data-s="2"]{border-top-color:var(--amber)}
.stat[data-s="1"]{border-top-color:var(--red)}
.stat-n{display:block;font-size:clamp(38px,5.6vw,64px);font-weight:800;font-stretch:112%;letter-spacing:-.05em;line-height:.85}
.stat[data-s="3"] .stat-n{color:var(--green-ink)}
.stat[data-s="2"] .stat-n{color:var(--amber-ink)}
.stat[data-s="1"] .stat-n{color:var(--red-ink)}
.stat[data-s="0"] .stat-n{color:var(--ink-faint)}
.stat-k{display:block;margin-top:12px;font-family:var(--mono);font-size:10px;letter-spacing:.1em;text-transform:uppercase;
  line-height:1.5;color:var(--ink-soft)}

/* ── controls ── */
.controls{position:sticky;top:0;z-index:5;width:100vw;margin-inline:calc(50% - 50vw);
  background:var(--paper);border-bottom:1px solid var(--rule);
  padding:12px var(--pad) max(12px,env(safe-area-inset-top));display:flex;flex-wrap:wrap;gap:12px 30px;align-items:center}
.group{display:flex;align-items:center;gap:11px;flex-wrap:wrap;min-width:0}
.group-label{font-family:var(--mono);font-size:10px;letter-spacing:.11em;text-transform:uppercase;color:var(--ink-faint)}
.chips{display:flex;gap:0;flex-wrap:wrap;border:1px solid var(--rule-soft)}
.chip{white-space:nowrap;background:transparent;border:0;border-right:1px solid var(--rule-soft);border-radius:0;padding:7px 15px;
  font-family:var(--mono);font-size:10.5px;font-weight:500;letter-spacing:.07em;text-transform:uppercase;color:var(--ink-soft);
  transition:background-color 160ms var(--ease-out),color 160ms var(--ease-out)}
.chip:last-child{border-right:0}
.chip[aria-pressed="true"]{background:var(--ink);color:var(--paper)}
.chip:focus-visible{outline:2px solid var(--focus);outline-offset:-2px;z-index:1;position:relative}

/* ── points ── */
.area{margin-top:52px}
.area-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;padding-bottom:12px;border-bottom:3px solid var(--rule)}
.area-head h3{font-size:clamp(20px,2.6vw,30px);font-weight:800;font-stretch:108%;text-transform:uppercase;letter-spacing:-.03em;
  line-height:1;margin:0;display:flex;flex-direction:column;gap:9px}
.area-pre{font-family:var(--mono);font-size:10px;font-weight:500;letter-spacing:.14em;color:var(--accent);text-transform:uppercase}
.area-count{font-family:var(--mono);font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-soft);white-space:nowrap}
.point{display:grid;grid-template-columns:var(--gutter) 1fr;gap:24px;padding:20px 0;border-bottom:1px solid var(--rule-soft);scroll-margin-top:96px}
.point.flash{animation:wash 1500ms var(--ease-out)}
@keyframes wash{0%,55%{background:color-mix(in srgb,var(--accent) 22%,transparent)}}
.boxes{display:flex;gap:4px;padding-top:3px}
.box{width:30px;height:30px;border-radius:0;border:1.5px solid var(--ink-faint);background:transparent;color:var(--ink-faint);
  font-family:var(--mono);font-size:11.5px;font-weight:500;line-height:1;display:flex;align-items:center;justify-content:center;padding:0;
  transition:background-color 160ms var(--ease-out),border-color 160ms var(--ease-out),color 160ms var(--ease-out),transform 140ms var(--ease-out)}
.box:active{transform:scale(.9)}
.box:focus-visible{outline:2px solid var(--focus);outline-offset:2px;z-index:1}
.box[data-state="1"]{background:var(--red);border-color:var(--red);color:var(--on-red)}
.box[data-state="2"]{background:var(--amber);border-color:var(--amber);color:var(--on-amber)}
.box[data-state="3"]{background:var(--green);border-color:var(--green);color:var(--on-green)}
.point-id{font-family:var(--mono);font-size:10.5px;letter-spacing:.08em;color:var(--ink-faint);margin-bottom:6px}
.point-title{font-size:17px;font-weight:700;line-height:1.28;letter-spacing:-.015em;margin:0 0 6px}
.point-detail{margin:0;color:var(--ink-soft);font-size:13.5px;line-height:1.6;max-width:66ch}

.deck-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-top:52px;padding-bottom:12px;border-bottom:3px solid var(--rule)}
.deck-head h3{font-size:clamp(22px,3vw,34px);font-weight:800;font-stretch:108%;text-transform:uppercase;letter-spacing:-.032em;margin:0}
.deck-head span{font-family:var(--mono);font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-soft)}
.deck-note{margin:16px 0 22px;font-size:13px;color:var(--ink-soft);max-width:60ch}
.deck{display:grid;grid-template-columns:repeat(auto-fill,minmax(290px,1fr));gap:1px;background:var(--rule-soft);border:1px solid var(--rule-soft)}
.qcard{background:var(--paper);border:0;border-top:4px solid var(--accent);padding:18px 19px 16px;break-inside:avoid}
.qcard.red{border-top-color:var(--red)}
.qcard.amber{border-top-color:var(--amber)}
.qcard-head{display:flex;justify-content:space-between;align-items:baseline;gap:10px;margin-bottom:8px}
.qcard-head .n{font-family:var(--mono);font-size:10px;font-weight:600;letter-spacing:.14em}
.qcard.red .n{color:var(--red-ink)}
.qcard.amber .n{color:var(--amber-ink)}
.qcard-head .refs{font-family:var(--mono);font-size:9.5px;color:var(--ink-faint)}
.qcard h4{font-size:16px;font-weight:700;letter-spacing:-.018em;margin:0 0 7px;line-height:1.24}
.qcard .front{margin:0 0 9px;font-size:12.5px;color:var(--ink-soft)}
.qcard ul{margin:0;padding-left:15px}
.qcard li{font-size:12.5px;line-height:1.5;margin-bottom:5px}
.qz{background:var(--panel);border:0;border-left:4px solid var(--accent);padding:19px 21px 17px;margin-bottom:10px}
.qz-head{display:flex;justify-content:space-between;align-items:baseline;gap:12px;margin-bottom:10px}
.qz-head .n{font-family:var(--mono);font-size:10px;font-weight:600;letter-spacing:.14em;color:var(--accent)}
.qz-head .marks{font-family:var(--mono);font-size:10px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-faint)}
.qz .stem{margin:0 0 12px;font-size:14.5px;line-height:1.55}
.qz ol.opts{margin:0 0 12px;padding-left:20px}
.qz ol.opts li{font-size:13.5px;margin-bottom:4px}
.qz .reveal{background:transparent;border:1px solid var(--rule-soft);border-radius:0;padding:7px 15px;
  font-family:var(--mono);font-size:10px;letter-spacing:.09em;text-transform:uppercase;color:var(--ink-soft);
  transition:border-color 160ms var(--ease-out),color 160ms var(--ease-out),background-color 160ms var(--ease-out)}
.qz .reveal:focus-visible{outline:2px solid var(--focus);outline-offset:2px}
.qz .ans{margin-top:13px;padding-top:13px;border-top:1px solid var(--rule-soft)}
.qz .ans p{margin:0 0 8px;font-family:var(--mono);font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:var(--ink-faint)}
.qz .ans ul{margin:0;padding-left:15px}
.qz .ans li{font-size:13.5px;line-height:1.5;margin-bottom:5px}
.qz .src{margin:11px 0 0;font-size:11.5px;color:var(--ink-faint)}
.papers{margin-top:32px;padding:18px 20px;border:0;border-left:4px solid var(--ink);background:var(--panel);font-size:13px;color:var(--ink-soft)}
.papers b{color:var(--ink);font-weight:700}
.print-row{margin-top:26px;display:flex;gap:9px;flex-wrap:wrap;align-items:center}
.print-row .hint{font-size:12.5px;color:var(--ink-faint)}
.empty{margin-top:48px;padding:52px 32px;border:1px solid var(--rule-soft);background:var(--panel);text-align:center}
.empty strong{display:block;font-size:24px;font-weight:800;font-stretch:108%;text-transform:uppercase;letter-spacing:-.03em;margin-bottom:9px}
.empty span{color:var(--ink-soft);font-size:13.5px}

/* ── sync + footer ── */
.sync{margin-top:56px;padding:22px 24px;border:0;border-left:4px solid var(--ink-faint);background:var(--panel)}
.sync[data-live="true"]{border-left-color:var(--green)}
.sync[data-live="warn"]{border-left-color:var(--amber)}
.sync-head{font-family:var(--mono);font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--ink-faint);margin:0 0 9px}
.sync-status{margin:0 0 15px;font-size:13.5px;max-width:60ch;color:var(--ink-soft)}
.sync-status b{color:var(--ink);font-weight:700}
.sync-actions{display:flex;flex-wrap:wrap;gap:8px}
footer{margin-top:40px;padding-top:22px;border-top:3px solid var(--rule);display:flex;flex-wrap:wrap;gap:12px 10px;align-items:center;font-size:12.5px;color:var(--ink-soft)}
.ghost{background:transparent;border:1px solid var(--rule-soft);border-radius:0;padding:8px 16px;
  font-family:var(--mono);font-size:10px;letter-spacing:.09em;text-transform:uppercase;
  transition:border-color 160ms var(--ease-out),background-color 160ms var(--ease-out),color 160ms var(--ease-out)}
.ghost:focus-visible{outline:2px solid var(--focus);outline-offset:2px}
.ghost.danger{color:var(--red-ink)}
.status{margin-left:auto;text-align:right;font-family:var(--mono);font-size:10.5px;letter-spacing:.04em}
.status[data-warn="true"]{color:var(--red-ink)}
.colophon{flex-basis:100%;margin:0;max-width:62ch;color:var(--ink-faint);font-size:12px}
.hidden{display:none !important}
.sr-only{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}

@media (hover:hover) and (pointer:fine){
  .backlink:hover{color:var(--ink)}
  .subject:hover{background:var(--panel);padding-left:18px}
  .cell:hover{outline:2px solid var(--ink);outline-offset:2px;z-index:1}
  .chip:hover{background:var(--track);color:var(--ink)}
  .chip[aria-pressed="true"]:hover{background:var(--ink);color:var(--paper)}
  .box:hover{border-color:var(--ink);color:var(--ink)}
  .box[data-state="1"]:hover{color:var(--on-red)}
  .box[data-state="2"]:hover{color:var(--on-amber)}
  .box[data-state="3"]:hover{color:var(--on-green)}
  .qz .reveal:hover{border-color:var(--ink);color:var(--ink);background:var(--track)}
  .ghost:hover{border-color:var(--ink);color:var(--ink)}
  .ghost.danger:hover{border-color:var(--red-ink);color:var(--red-ink)}
}
@media (pointer:coarse){
  .box{width:44px;height:44px;font-size:13.5px}
  .boxes{gap:5px}
  :root{--gutter:151px}
  .chip{padding:12px 16px;font-size:11px}
  .ghost,.qz .reveal{padding:12px 18px}
  .cell{height:34px}
  .cell::after{inset:-6px -2px}
}
@media (prefers-contrast:more){
  :root{--rule-soft:var(--rule);--ink-soft:var(--ink)}
  .box{border-width:2px}
}
html.theming *,html.theming *::before,html.theming *::after{
  transition-property:background-color,border-color,color,box-shadow,outline-color;
  transition-duration:320ms;transition-timing-function:var(--ease-in-out)}

@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*::before,*::after{animation-duration:.01ms !important;animation-iteration-count:1 !important;transition-duration:.01ms !important}
  .cell{animation:none}
  .subject:hover{padding-left:0}
  .box:active{transform:none}
}

@media print{
  body{background:#fff;color:#000}
  .wrap{max-width:none;padding:0}
  .masthead,.subject-band{padding:0 0 10px;background:none;color:#000}
  .backlink,.controls,.map,.stats,.sync,footer,#home,.deck-note,.print-row,.papers{display:none !important}
  .deck{grid-template-columns:repeat(2,1fr);gap:9px;background:none;border:0}
  .qcard{background:#fff;border:1px solid #bbb;border-top-width:3px}
  .deck-head{page-break-after:avoid}
  .qz .ans{display:block}
  .reveal{display:none}
}

@media (max-width:900px){
  .subject{grid-template-columns:1fr;gap:16px}
  .stats{grid-template-columns:repeat(2,minmax(0,1fr))}
  .stat:nth-child(2){border-right:0}
  .stat:nth-child(3),.stat:nth-child(4){border-top-width:3px}
}
@media (max-width:620px){
  :root{--gutter:96px;--pad:16px}
  .wrap{padding-left:max(16px,env(safe-area-inset-left));padding-right:max(16px,env(safe-area-inset-right));padding-bottom:calc(80px + env(safe-area-inset-bottom))}
  .masthead{padding:34px 0 0}
  .map-row,.map-legend,.totals-row{grid-template-columns:22px 1fr 64px;gap:9px}
  .map-groups{gap:4px}.map-group{gap:1px}
  .cell{height:22px;min-width:1px}
  .count{font-size:10px}
  .map-legend{display:none}
  .point{grid-template-columns:1fr;gap:12px}
  .status{margin-left:0;text-align:left;flex-basis:100%}
  .legend-key{flex-direction:column}
  .key{border-right:0;border-bottom:1px solid var(--rule-soft)}
  .key:last-child{border-bottom:0}
  .controls{gap:8px 18px}
  .group{flex-wrap:nowrap;width:100%;gap:10px}
  .group-label{flex:0 0 auto}
  .chips{flex-wrap:nowrap;overflow-x:auto;overscroll-behavior-x:contain;scrollbar-width:none}
  .chips::-webkit-scrollbar{display:none}
}
@media (max-width:620px) and (pointer:coarse){
  .chip{padding:10px 14px}
  .cell{height:26px}
}

/* Midnight: matte navy panels and luminous, high-contrast type. */
@media screen {
:root{
  color-scheme:dark;
  --paper:#101522;--paper-deep:#0b101b;--ink:#edf0fc;--ink-soft:#b8c1dc;--ink-faint:#a0aecb;
  --rule:#485575;--rule-soft:#303c56;--track:#29354d;
  --glass:#192237;--glass-strong:#212d44;--edge:#3a4968;--edge-low:#303e59;
  --shade:rgba(0,0,0,.2);--shade-deep:rgba(0,0,0,.38);
  --red:#ef988d;--amber:#edc77c;--green:#80d3bd;
  --on-red:#291110;--on-amber:#251b08;--on-green:#0b2420;
  --red-ink:#ffaaa0;--amber-ink:#edc77c;--green-ink:#80d3bd;
  --focus:#b6acff;--r-surface:12px;--r-pill:8px;--r-box:7px;
  --sans:"Outfit","Segoe UI",system-ui,sans-serif;
}
body::before{background:radial-gradient(ellipse at 85% 0%,rgba(130,110,232,.12),transparent 55%)}
.pane,.totals,.subject,.qcard,.qz,.sync,.papers,.empty,.backlink,.ghost,.chip{backdrop-filter:none;-webkit-backdrop-filter:none;box-shadow:0 8px 24px -18px #000}
h1{font-weight:500;letter-spacing:-.045em}
.section-label{color:#b6acff;letter-spacing:.16em}
.totals{border-top:2px solid #a599ee}
.subject{border-top:2px solid var(--swatch,var(--accent))}
.subject h2{font-weight:500}
.qz,.qcard{border-left:3px solid var(--accent)}
.practice-input{background:#101a2c}
}

/* Notebook: cream paper, ruled background and editorial serif headings. */
@media screen {
:root{
  color-scheme:light;
  --paper:#f5f0e5;--paper-deep:#eee5d4;--ink:#292f36;--ink-soft:#515c63;--ink-faint:#616a6f;
  --rule:#9c998e;--rule-soft:#d7cfc0;--track:#e2dbcd;
  --glass:#fffcf5;--glass-strong:#fffdf8;--edge:#fffdf8;--edge-low:#d8cfbd;
  --shade:rgba(78,63,35,.06);--shade-deep:rgba(78,63,35,.16);
  --red:#b94d3d;--amber:#d3a345;--green:#397462;
  --on-red:#fff;--on-amber:#29200c;--on-green:#fff;
  --red-ink:#a53e30;--amber-ink:#79550e;--green-ink:#2d6453;
  --focus:#315d82;--r-surface:4px;--r-pill:4px;--r-box:3px;
  --sans:"Segoe UI",system-ui,sans-serif;
}
body::before{background:repeating-linear-gradient(180deg,transparent 0,transparent 31px,rgba(78,107,127,.075) 31px,rgba(78,107,127,.075) 32px)}
h1,h2,.qcard h4,.deck-head h3{font-family:Georgia,"Times New Roman",serif;font-weight:400;letter-spacing:-.035em}
h1{font-size:clamp(38px,5.6vw,66px)}
.masthead{border-bottom:2px solid var(--ink);padding-bottom:26px}
.standfirst{font-size:15px;line-height:1.75}
.pane,.totals,.subject,.qcard,.qz,.sync,.papers,.empty,.backlink,.ghost,.chip{backdrop-filter:none;-webkit-backdrop-filter:none;box-shadow:2px 3px 0 rgba(111,92,61,.10)}
.section-label{font-family:var(--mono);letter-spacing:.16em}
#subject-list{display:flex;flex-direction:column;gap:14px}
#subject-list .subject,#subject-list .subject:first-child{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,320px);align-items:center;gap:28px;border-left:4px solid var(--swatch,var(--accent))}
#subject-list .subject h2,#subject-list .subject:first-child h2{font-size:27px}
.qz,.qcard{border-top:3px double var(--rule-soft)}
.practice-input{background-color:#fffdf8;background-image:repeating-linear-gradient(180deg,transparent 0,transparent calc(1.6em - 1px),rgba(78,107,127,.11) calc(1.6em - 1px),rgba(78,107,127,.11) 1.6em);background-origin:content-box;background-clip:content-box;line-height:1.6}
@media (max-width:620px){
  #subject-list .subject,#subject-list .subject:first-child{grid-template-columns:minmax(0,1fr);gap:18px}
}
}

.footer-rating-actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.theme-picker{display:inline-flex;align-items:center;gap:8px;max-width:100%;min-width:0}
.theme-picker-label{flex-shrink:0}
.theme-picker-label{font-family:var(--mono);font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--ink-soft)}
.theme-options{display:inline-flex;flex-wrap:wrap;min-width:0;gap:4px;padding:4px;border:1px solid var(--rule-soft);border-radius:var(--r-pill,0);background:var(--paper)}
.theme-option{appearance:none;font:500 13px var(--sans);padding:10px 12px;min-height:44px;cursor:pointer;border:1px solid transparent;border-radius:var(--r-pill,0);background:transparent;color:var(--ink-soft)}
.theme-option[aria-pressed="true"]{background:var(--ink);color:var(--paper)}
.theme-option:focus-visible{outline:2px solid var(--focus);outline-offset:3px}

.practice-toolbar,.practice-actions{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}
.practice-summary{font-weight:600;margin-bottom:4px}
.practice-save,.practice-help{font-size:12px;color:var(--ink-soft);margin:6px 0 16px}
.practice-input-label{display:block;font-size:13px;font-weight:500;margin-bottom:7px}
.practice-input{display:block;width:100%;min-height:130px;resize:vertical;padding:13px;border:1px solid var(--rule-soft);border-radius:var(--r-box,0);background:var(--paper);color:var(--ink);font:inherit;line-height:1.6;margin:0 0 12px}
.practice-input:focus-visible,.practice-mark select:focus-visible,.practice-choice:focus-within,.practice-check:focus-within{outline:2px solid var(--focus);outline-offset:3px}
.practice-options{padding:0;margin:12px 0;border:0;min-width:0}
.practice-choice,.practice-check{display:flex;align-items:flex-start;gap:10px;font-size:14px;line-height:1.5;padding:10px;cursor:pointer;overflow-wrap:anywhere}
.practice-choice{border:1px solid var(--rule-soft);border-radius:var(--r-box,0);margin-bottom:7px}
.practice-choice:has(input:checked){border-color:var(--accent);background:var(--track)}
.practice-choice input,.practice-check input{flex-shrink:0;width:17px;height:17px;margin:3px 0;accent-color:var(--accent)}
.practice-feedback{font-size:13px;color:var(--ink-soft);min-height:20px}
.practice-mark{display:flex;gap:12px;align-items:center;font-size:14px;margin-top:14px}
.practice-mark select{background:var(--paper);color:var(--ink);border:1px solid var(--rule);padding:9px;font:inherit;border-radius:var(--r-box,0);max-width:100%}
.qz .reveal:disabled{opacity:.5;cursor:not-allowed}

@media (max-width:480px){.theme-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));border-radius:var(--r-box,0)}.theme-option{padding-inline:10px}}
@media print{.theme-picker{display:none}}
